typedef float vm_num_t;

class stringx {
public:
    char *chars;
    const char *c_str() const { return chars; }
    stringx operator+(const char *) const;
    stringx operator+(const stringx &) const;
};

class script_object {
public:
    stringx get_name() const;
};

class script_executable {
public:
    stringx get_fullname() const;
};

class vm_thread {
public:
    script_object *get_instance() const;
    script_executable *get_executable() const;
};

class vm_stack {
public:
    int salloc;
    char *buffer;
    char *SP;
    vm_thread *my_thread;
    char *get_SP() const { return SP; }
    void pop(int n) { SP -= n; }
    bool push(const char *, int);
    vm_thread *get_thread() const { return my_thread; }
};

class __attribute__((aligned(16))) pstring {
    unsigned long pchunk[4];
public:
    pstring(const char *text) { pack_string(text); }
    void pack_string(const char *);
};

class game_info {
public:
    bool get_num(const pstring &, vm_num_t &) const;
};

class game {
    char padding[0x200];
public:
    game_info info;
};

extern game *g_game_ptr;
void error(const stringx &);

__asm__(".equ g_game_ptr, 0x0046AC64");
__asm__(".equ pack_string__7pstringPCc, 0x003354D0");
__asm__(".equ get_num__C9game_infoRC7pstringRf, 0x00277C88");
__asm__(".equ push__8vm_stackPCci, 0x00354158");
__asm__(".equ error__FRC7stringx, 0x001DFAB0");

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    };
};

#define SLF_PARMS \
  stack.pop(sizeof(parms_t)); \
  parms_t* parms = (parms_t*)stack.get_SP()
#define SLF_RETURN \
  if (!stack.push((char*)&result,sizeof(result)) ) \
    error( stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname() )
#define SLF_DONE return true

class slf_get_game_info_num_t : public script_library_class::function {
public:
    struct parms_t {
      stringx *att;
    };
    bool operator()(vm_stack& stack,entry_t entry);
};

bool slf_get_game_info_num_t::operator()(vm_stack& stack,entry_t entry)
{
  SLF_PARMS;

  vm_num_t result = 0;

  pstring p(parms->att->c_str());
  g_game_ptr->info.get_num(p, result);

  SLF_RETURN;
  SLF_DONE;
}
